ption>`).join('')}</select></label></div><label>${TEXT.frequency}<select name="frequency" required><option value="weekly">${TEXT.weekly}</option><option value="monthly" selected>${TEXT.monthly}</option><option value="yearly">${TEXT.yearly}</option></select></label><div class="field-row"><label>${TEXT.startOn}<input name="start_on" type="date" required></label><label>${TEXT.endOn}<input name="end_on" type="date"></label></div><p class="error" id="recurring-error" role="alert"></p><div class="dialog-actions"><button type="button" class="secondary" id="cancel-recurring">${TEXT.cancel}</button><button type="submit" class="primary">${TEXT.save}</button></div></form></dialog><dialog id="cancel-recurring-dialog"><div class="dialog-head"><h2>${TEXT.cancelRecurringTitle}</h2></div><p>${TEXT.cancelRecurringQuestion}</p><div class="dialog-actions"><button type="button" class="secondary" id="keep-recurring">${TEXT.cancel}</button><button type="button" class="primary danger-button" id="confirm-cancel-recurring">${TEXT.cancelRule}</button></div></dialog><dialog id="delete-account-dialog"><form id="delete-account-form"><div class="dialog-head"><h2>${TEXT.deleteAccountTitle}</h2><button type="button" class="icon" id="close-delete-account">×</button></div><p>${TEXT.deleteAccountWarning}</p><label>${TEXT.passwordConfirmation}<input name="password" type="password" autocomplete="current-password" required></label><label>${TEXT.typeDelete}<input name="confirmation" required autocomplete="off"></label><p class="error" id="delete-account-error" role="alert"></p><div class="dialog-actions"><button type="button" class="secondary" id="cancel-delete-account">${TEXT.cancel}</button><button type="submit" class="primary danger-button">${TEXT.deleteAccount}</button></div></form></dialog>`;
