function activateSection(section, updateHash=true){
  if(!['overview','expenses','cards','income'].includes(section))section='overview';
  currentSection=section;
  document.querySelectorAll('[data-page]').forEach(page=>{page.hidden=page.dataset.page!==section});
  document.querySelectorAll('[data-section]').forEach(link=>{const active=link.dataset.section===section;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')});
  const title={overview:TEXT.dashboard,expenses:TEXT.expenses,cards:TEXT.myCards,income:TEXT.myIncome}[section];
  const heading=document.querySelector('#section-title');if(heading)heading.textContent=title;
  if(updateHash)history.replaceState(null,'',`#${section}`);
}
function openExpense(exp){const dlg=document.querySelector('#expense-dialog'),f=document.querySelector('#expense-form');f.reset();dlg.querySelector('h2').textContent=exp?TEXT.editExpense:TEXT.addExpense;f.elements.id.value=exp?.id||'';f.elements.amount.value=exp?exp.amount_minor/100:'';f.elements.spent_on.value=exp?.spent_on||localDate();f.elements.first_installment_on.value=exp?.spent_on||localDate();f.elements.description.value=exp?.description||'';f.elements.category_id.value=exp?.category_id||state.categories[0]?.id||'';f.elements.payment_method_id.value=exp?.payment_method_id||state.payment_methods[0]?.id||'';f.elements.card_id.value=exp?.card_id||'';f.elements.installments_count.value=exp?.installments_count||1;f.elements.note.value=exp?.note||'';document.querySelector('#form-error').textContent='';const details=document.querySelector('#card-purchase-details'),firstField=document.querySelector('#first-installment-field');details.open=Boolean(exp?.card_id)||state.payment_methods.find(item=>String(item.id)===f.elements.payment_method_id.value)?.name==='Kredi kartı';firstField.hidden=f.elements.installments_count.value==='1';dlg.showModal()}
