async function saveBudget(e){e.preventDefault();const form=Object.fromEntries(new FormData(e.target)),button=e.target.querySelector('button[type=submit]'),error=document.querySelector('#budget-error');button.disabled=true;error.textContent='';try{await api('/api/budgets',{method:'POST',body:JSON.stringify(form)});await loadApp()}catch(err){error.textContent=err.message}finally{button.disabled=false}}
function addCategory(){document.querySelector('#category-form').reset();document.querySelector('#category-error').textContent='';document.querySelector('#category-dialog').showModal();document.querySelector('#category-form [name=name]').focus()}
async function saveCategory(e){e.preventDefault();const form=e.target,button=form.querySelector('button.primary');if(button.disabled)return;button.disabled=true;button.textContent=TEXT.saving;const data=Object.fromEntries(new FormData(form));try{await api('/api/categories',{method:'POST',body:JSON.stringify(data)});document.querySelector('#category-dialog').close();await loadApp()}catch(error){document.querySelector('#category-error').textContent=error.message}finally{button.disabled=false;button.textContent=TEXT.save}}
let importCsvText="", importPreviewRows=[];
function openImport(){const form=document.querySelector('#import-form');form.reset();importCsvText="";importPreviewRows=[];document.querySelector('#import-preview').innerHTML='';document.querySelector('#import-error').textContent='';document.querySelector('#save-import').disabled=true;document.querySelector('#import-dialog').showModal()}
function closeImport(){document.querySelector('#import-dialog').close();importCsvText="";importPreviewRows=[]}
async function previewImport(){const file=document.querySelector('#import-form [name=csv_file]').files[0],error=document.querySelector('#import-error'),button=document.querySelector('#preview-import');error.textContent='';if(!file){error.textContent=TEXT.selectFile;return}if(file.size>1000000){error.textContent='CSV dosyası en fazla 1 MB olabilir.';return}button.disabled=true;button.textContent=TEXT.loading;try{importCsvText=await file.text();const result=await api('/api/import/preview',{method:'POST',body:JSON.stringify({csv:importCsvText})});importPreviewRows=result.rows;renderImportPreview();document.querySelector('#save-import').disabled=!importPreviewRows.some(r=>!r.errors.length&&!r.duplicate)||!importPreviewRows.some(r=>!r.errors.length); }catch(e){error.textContent=e.message;document.querySelector('#save-import').disabled=true}finally{button.disabled=false;button.textContent=TEXT.preview}}
function renderImportPreview(){const host=document.querySelector('#import-preview');host.innerHTML=`<div class="import-table-wrap"><table class="import-table"><thead><tr><th>Satır</th><th>Tarih</th><th>Açıklama</th><th>Tutar</th><th>Durum</th><th>Dahil et</th></tr></thead><tbody>${importPreviewRows.map((r,i)=>`<tr class="${r.errors.length?'invalid-row':r.duplicate?'duplicate-row':''}"><td>${r.row}</td><td>${esc(r.date||'—')}</td><td>${esc(r.description||'—')}${r.errors.length?`<small>${r.errors.map(esc).join('<br>')}</small>`:''}</td><td>${r.amount_minor===null?'—':money(r.amount_minor)}</td><td>${r.errors.length?TEXT.invalid:r.duplicate?TEXT.duplicate:TEXT.success}</td><td>${!r.errors.length?`<input type="checkbox" data-import-row="${i}" ${!r.duplicate?'checked':''} ${r.duplicate?'aria-label="Olası tekrar satırını içe aktar"':''}>`:''}</td></tr>`).join('')}</tbody></table></div>`;host.querySelectorAll('[data-import-row]').forEach(box=>box.onchange=()=>{document.querySelector('#save-import').disabled=!host.querySelector('[data-import-row]:checked')})}
async function saveImport(e){e.preventDefault();const button=document.querySelector('#save-import');if(button.disabled||!importCsvText)return;button.disabled=true;button.textContent=TEXT.saving;try{const selected_rows=[...document.querySelectorAll('[data-import-row]:checked')].map(box=>importPreviewRows[Number(box.dataset.importRow)].row);const result=await api('/api/import',{method:'POST',body:JSON.stringify({csv:importCsvText,selected_rows})});closeImport();await loadApp();document.querySelector('#action-error').textContent=`${result.imported} ${TEXT.importDone}${result.invalid_rows.length?` ${result.invalid_rows.length} hatalı satır atlandı.`:''}${result.duplicate_rows.length?` ${result.duplicate_rows.length} olası tekrar atlandı.`:''}`}catch(error){document.querySelector('#import-error').textContent=error.message;button.disabled=false}finally{button.textContent=TEXT.import}}
function openRecurring(rule){const dialog=document.querySelector('#recurring-dialog'),form=document.querySelector('#recurring-form');form.reset();form.elements.id.value=rule?.id||'';form.elements.description.value=rule?.description||'';form.elements.amount.value=rule?rule.amount_minor/100:'';form.elements.category_id.value=rule?.category_id||'';form.elements.payment_method_id.value=rule?.payment_method_id||'';form.elements.frequency.value=rule?.frequency||'monthly';form.elements.start_on.value=rule?.start_on||localDate();form.elements.end_on.value=rule?.end_on||'';document.querySelector('#recurring-form-title').textContent=rule?TEXT.editRecurring:TEXT.recurringTitle;document.querySelector('#recurring-error').textContent='';dialog.showModal()}
