async function saveRecurring(e){e.preventDefault();const form=e.target,button=form.querySelector('button[type=submit]'),error=document.querySelector('#recurring-error');if(button.disabled)return;button.disabled=true;button.textContent=TEXT.saving;try{await api('/api/recurring',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});closeRecurring();await loadApp()}catch(err){error.textContent=err.message}finally{button.disabled=false;button.textContent=TEXT.save}}
async function changeRecurringStatus(id,status){try{await api(`/api/recurring/${id}/status`,{method:'POST',body:JSON.stringify({status})});await loadApp()}catch(error){document.querySelector('#action-error').textContent=error.message}}
async function completeOccurrence(button){if(button.disabled)return;button.disabled=true;try{const result=await api(`/api/recurring/${button.dataset.completeRecurring}/occurrences/${button.dataset.occurrence}/complete`,{method:'POST',body:'{}'});await loadApp();document.querySelector('#action-error').textContent=result.created?TEXT.occurrenceSaved:'Bu plan zaten harcama kayıtlarına eklenmiş.'}catch(error){document.querySelector('#action-error').textContent=error.message;button.disabled=false}}
